const body = $input.first().json.body || {};
const clientId = body.clientId;

if (!clientId) {
  return [{ json: { success: false, error: 'INVALID_CLIENT_ID', message: 'clientId is required' } }];
}

const clientNames = {
  '1': { name: 'Joseph Bui', brand: 'Open House Finance', firstName: 'Joseph' },
  '2': { name: 'Matt Tixier', brand: 'True Mortgage', firstName: 'Matt' },
  '3': { name: 'Richard Weinberg', brand: 'Rich Capital', firstName: 'Richard' },
  '4': { name: 'John Flanders', brand: 'Karpata Finance', firstName: 'John' },
  '5': { name: 'Matthew Silva', brand: 'Woodlands', firstName: 'Matthew' },
  '6': { name: 'Derek Schaffer', brand: 'Investor Capital Loans NJ', firstName: 'Derek' },
  '7': { name: 'Paul Healey', brand: 'Spectrum One Mortgage', firstName: 'Paul' },
  '8': { name: 'Jason Gilmore', brand: 'James Paxton Mortgages', firstName: 'Jason' },
  '9': { name: 'Dan Nguyen', brand: 'Win Capital LLC', firstName: 'Dan' },
  '10': { name: 'Chad', brand: 'Canada Mortgage Direct', firstName: 'Chad' },
  '11': { name: 'Kelto', brand: 'Quebec Refinance', firstName: 'Kelto' },
  '12': { name: 'Shaun Woods', brand: 'Opus Grenero', firstName: 'Shaun' },
  '13': { name: 'Dean Onwumere', brand: 'Part 2 Lending', firstName: 'Dean' },
  '14': { name: 'Benjamin Gerritsen', brand: 'Mortgage Miracles', firstName: 'Benjamin' },
  '15': { name: 'Natalie x Brian', brand: 'NB Capital', firstName: 'Natalie' }
};

const client = clientNames[clientId];
if (!client) {
  return [{ json: { success: false, error: 'INVALID_CLIENT_ID', message: 'Client ID not found' } }];
}

return [{ json: { clientId, ...client } }];

const client = $('Resolve Client').first().json;
const metaResponse = $('Fetch Performance').first().json;
const ghlResponse = $('Fetch Pipeline').first().json;

const metaData = (metaResponse.body || metaResponse);
const ghlData = (ghlResponse.body || ghlResponse);
const summary = metaData.data?.summary || {};
const pipeline = ghlData.pipeline || {};
const stages = pipeline.stages || [];

const trueCpl = summary.trueCpl || 0;
const trueLeads = summary.trueLeads || 0;
const apptCount = stages.find(s => s.name?.includes('Appointment'))?.count || 0;
const appCount = stages.find(s => s.name?.includes('Application'))?.count || 0;
const closedCount = stages.find(s => s.name?.includes('Closed'))?.count || 0;

const status = trueCpl <= 50 ? 'GREEN' : trueCpl <= 80 ? 'YELLOW' : 'RED';

const systemPrompt = `You are the AI account manager for ${client.name} at ${client.brand}.

Your role is to answer questions about their Meta advertising campaigns and mortgage lead generation performance.

Current performance as of ${new Date().toISOString().split('T')[0]}:
- Cost per lead: $${trueCpl} (target: below $50)
- Leads generated this month: ${trueLeads}
- Appointments set: ${apptCount}
- Applications submitted: ${appCount}
- Closed deals: ${closedCount}
- Campaign status: ${status}

Guidelines:
- Answer questions about performance, results, and what we are doing
- Do not promise specific CPL numbers or guaranteed results
- If asked about specific leads, say you can pull the data and the team will follow up
- Offer to schedule a call with Cam if the client has complex questions
- Keep responses conversational and under 3 sentences
- If status is RED, acknowledge the issue and explain the fix in progress`;

const greeting = `Hi ${client.firstName}! I'm your AI account manager. Your campaigns generated ${trueLeads} leads this month at $${trueCpl} cost per lead. What questions do you have?`;

return [{
  json: {
    clientId: client.clientId,
    clientName: client.name,
    brand: client.brand,
    systemPrompt,
    greeting,
    agentName: client.name + ' Account Manager'
  }
}];

const config = $('Build Agent Config').first().json;
const agentResponse = $('Create Play.ai Agent').first().json;
const agentData = agentResponse.body || agentResponse;

if (agentData.id) {
  return [{
    json: {
      success: true,
      agentId: agentData.id,
      embedUrl: agentData.embedUrl || agentData.embed_url || null,
      agentName: config.agentName
    }
  }];
}

return [{
  json: {
    success: false,
    error: 'PLAYAI_API_ERROR',
    message: 'Failed to create Play.ai agent: ' + JSON.stringify(agentData),
    retryable: true
  }
}];
